/**
 * MIME parsing via mailparser (MIT) — used by Zammad/osTicket-style inbound pipelines.
 * Auto-reply / bounce detection patterned after osTicket class.filter + RT CheckForAutoGenerated
 * (reimplemented — no GPL paste).
 * @see https://github.com/nodemailer/mailparser
 */
import { simpleParser, type Attachment } from 'mailparser';
import sanitizeHtml from 'sanitize-html';
import { ticketIdPrefix, ticketNumberPattern } from './ticket-id';

export type ParsedInboundEmail = {
  from: string;
  fromName?: string;
  to: string;
  subject: string;
  body: string;
  html?: string;
  inReplyTo?: string;
  references?: string[];
  attachments: { filename: string; content: Buffer; contentType?: string }[];
  isAutoReply: boolean;
  isBounce: boolean;
};

/** Header names that indicate machine-generated mail (osTicket/RT style table). */
const AUTO_REPLY_HEADER_HINTS: { name: string; denyExact?: string[] }[] = [
  { name: 'auto-submitted', denyExact: ['no'] },
  { name: 'x-autoreply' },
  { name: 'x-autoresponse' },
  { name: 'x-auto-response-suppress' },
  { name: 'precedence', denyExact: ['no'] },
  { name: 'x-precedence', denyExact: ['no'] },
  { name: 'x-loop' },
  { name: 'list-unsubscribe' },
];

const AUTO_SUBJECT_RE =
  /^(auto[-\s]?reply|automatic reply|out of office|ooo:|vacation|undeliverable|delivery status notification)/i;

const BOUNCE_FROM_RE = /(mailer-daemon|postmaster|mail delivery|noreply|no-reply)/i;

export function detectAutoReply(headers: Map<string, unknown> | { get: (k: string) => unknown }, subject: string): boolean {
  for (const hint of AUTO_REPLY_HEADER_HINTS) {
    const raw = headers.get(hint.name);
    if (raw == null) continue;
    const v = String(raw).toLowerCase().trim();
    if (!v) continue;
    if (hint.denyExact?.includes(v)) continue;
    if (hint.name === 'precedence' || hint.name === 'x-precedence') {
      if (v === 'bulk' || v === 'junk' || v === 'list' || v === 'auto_reply') return true;
      continue;
    }
    return true;
  }
  if (AUTO_SUBJECT_RE.test(subject.trim())) return true;
  return false;
}

export function detectBounce(
  headers: Map<string, unknown> | { get: (k: string) => unknown },
  from: string,
  subject: string,
): boolean {
  const returnPath = headers.get('return-path');
  if (returnPath != null) {
    const rp = String(returnPath).trim();
    if (rp === '<>' || rp === '') return true;
  }
  if (BOUNCE_FROM_RE.test(from)) return true;
  if (/undeliverable|delivery status|returned mail|mail delivery failed/i.test(subject)) return true;
  const ct = headers.get('content-type');
  if (ct && /delivery-status|multipart\/report/i.test(String(ct))) return true;
  return false;
}

export async function parseMimeSource(raw: string | Buffer): Promise<ParsedInboundEmail> {
  const parsed = await simpleParser(raw);
  const fromAddr = parsed.from?.value?.[0];
  const toAddr = parsed.to
    ? Array.isArray(parsed.to)
      ? parsed.to[0]?.value?.[0]
      : parsed.to.value?.[0]
    : undefined;

  const headers = parsed.headers;
  const from = fromAddr?.address ?? '';
  const subject = parsed.subject ?? '(no subject)';
  const isBounce = detectBounce(headers, from, subject);
  const isAutoReply = isBounce || detectAutoReply(headers, subject);

  const html = parsed.html
    ? sanitizeHtml(String(parsed.html), {
        allowedTags: sanitizeHtml.defaults.allowedTags.concat(['img', 'h1', 'h2', 'table', 'tr', 'td']),
        allowedAttributes: { ...sanitizeHtml.defaults.allowedAttributes, img: ['src', 'alt'] },
      })
    : undefined;

  const attachments = (parsed.attachments ?? []).map((a: Attachment) => ({
    filename: a.filename ?? 'attachment',
    content: a.content,
    contentType: a.contentType,
  }));

  return {
    from,
    fromName: fromAddr?.name,
    to: toAddr?.address ?? '',
    subject,
    body: parsed.text?.trim() || stripHtml(html ?? '') || '(empty body)',
    html,
    inReplyTo: parsed.inReplyTo ?? undefined,
    references: parsed.references
      ? String(parsed.references)
          .split(/\s+/)
          .filter(Boolean)
      : undefined,
    attachments,
    isAutoReply,
    isBounce,
  };
}

function stripHtml(html: string): string {
  return html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

export function extractTicketToken(subject: string, references?: string[]): string | null {
  const pattern = ticketNumberPattern();
  const prefix = ticketIdPrefix();
  const fromSubject = subject.match(pattern)?.[0];
  if (fromSubject) {
    const num = fromSubject.replace(new RegExp(`^${prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'i'), '');
    return `${prefix}${num}`;
  }
  if (references) {
    for (const ref of references) {
      const m = ref.match(pattern);
      if (m) {
        const num = m[0].replace(new RegExp(`^${prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'i'), '');
        return `${prefix}${num}`;
      }
    }
  }
  return null;
}
